// ============================================================
// COLLECTE TAVILY — 3 axes thématiques financiers
// Variables n8n requises : TAVILY_API_KEY
// ============================================================
const TAVILY_API_KEY = $vars.TAVILY_API_KEY;
const annee = new Date().getFullYear();

const searches = [
  {
    theme: 'banque_centrale',
    label: 'Banque Centrale & Politique Monétaire',
    query: `banque centrale europe BCE taux intérêt décision politique monétaire ${annee}`
  },
  {
    theme: 'macro',
    label: 'Indicateurs Macro-économiques',
    query: `inflation PIB croissance chômage indicateurs économiques France Europe ${annee}`
  },
  {
    theme: 'sectoriel',
    label: 'Sectoriel Fintech & Crédit',
    query: `fintech crédit bancaire réglementation financière secteur bancaire ${annee}`
  }
];

const tavilyData = {};
const errors = [];

for (const s of searches) {
  try {
    const res = await $http.request({
      method: 'POST',
      url: 'https://api.tavily.com/search',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${TAVILY_API_KEY}`
      },
      body: JSON.stringify({
        query: s.query,
        search_depth: 'advanced',
        max_results: 5,
        include_answer: true
      })
    });

    tavilyData[s.theme] = {
      label: s.label,
      answer: res.answer || '',
      articles: (res.results || []).map(r => ({
        title: r.title || '',
        excerpt: (r.content || '').substring(0, 300),
        url: r.url || ''
      }))
    };
  } catch (err) {
    errors.push(s.theme);
    tavilyData[s.theme] = {
      label: s.label,
      answer: 'Données indisponibles (erreur Tavily)',
      articles: []
    };
  }
}

return [{
  json: {
    tavilyData,
    tavilyErrors: errors,
    tavilyOk: errors.length < 3,
    collectedAt: new Date().toISOString()
  }
}];

// ============================================================
// CONSTRUCTION DU PROMPT LLM
// ============================================================
const { tavilyData, collectedAt, tavilyOk } = $input.first().json;

const dateLabel = new Date(collectedAt).toLocaleDateString('fr-FR', {
  day: '2-digit', month: 'long', year: 'numeric'
});

const formatTheme = (theme) => {
  const arts = (theme.articles || [])
    .map((a, i) => `  [${i+1}] ${a.title}\n      ${a.excerpt}`)
    .join('\n');
  return `Synthèse : ${theme.answer}\n\nSources récentes :\n${arts || '  (aucune source disponible)'}\n`;
};

const userPrompt = `Tu es un analyste financier expert en gestion des risques bancaires.
Date d'analyse : ${dateLabel}

## DONNÉES COLLECTÉES VIA TAVILY (Web Search IA)

### AXE 1 — ${tavilyData.banque_centrale.label}
${formatTheme(tavilyData.banque_centrale)}

### AXE 2 — ${tavilyData.macro.label}
${formatTheme(tavilyData.macro)}

### AXE 3 — ${tavilyData.sectoriel.label}
${formatTheme(tavilyData.sectoriel)}

## INSTRUCTIONS
Produis une analyse structurée OBLIGATOIREMENT en 5 sections avec les marqueurs suivants :

[1] RÉSUMÉ EXÉCUTIF
(3-4 lignes. Points clés pour les décideurs.)

[2] IMPACT BANQUE CENTRALE
(Implications sur le scoring crédit, les taux de prêt, la liquidité bancaire.)

[3] INDICATEURS MACRO-ÉCONOMIQUES
(Risques liés à l'inflation, croissance, emploi pour les portefeuilles de crédit.)

[4] ANALYSE SECTORIELLE
(Évolutions réglementaires et tendances fintech/crédit à surveiller.)

[5] RECOMMANDATIONS D'ADAPTATION DES RÈGLES MÉTIER
(3 recommandations concrètes et actionnables pour adapter les règles de décision crédit.)

Sois concis, structuré, orienté décision opérationnelle. Réponds uniquement en français.`;

return [{ json: { userPrompt, tavilyData, collectedAt, tavilyOk } }];

// ============================================================
// PARSER LA RÉPONSE LLM + FALLBACK si LLM indisponible
// ============================================================
const llmRaw = $input.first().json;
const prev = $('Construire Prompt LLM').first().json;
const { tavilyData, collectedAt } = prev;

const monthLabel = new Date(collectedAt).toLocaleDateString('fr-FR', {
  month: 'long', year: 'numeric'
});

let analysisText = '';
let confidence = 0.82;
let isFallback = false;

// Vérifier si le LLM a répondu correctement
if (llmRaw.choices && llmRaw.choices[0]?.message?.content) {
  analysisText = llmRaw.choices[0].message.content;
} else {
  // Fallback — rapport brut depuis les données Tavily
  isFallback = true;
  confidence = 0.45;
  analysisText = Object.values(tavilyData)
    .map(t => `### ${t.label}\n${t.answer}\n${(t.articles || []).map(a => `- ${a.title}: ${a.url}`).join('\n')}`)
    .join('\n\n');
}

// Extraire une section du rapport par son numéro [N]
const extractSection = (text, num) => {
  const regex = new RegExp(`\\[${num}\\][^\\[]*`, 's');
  const match = text.match(regex);
  if (!match) return '';
  return match[0].replace(/^\[\d+\][^\n]*\n?/, '').trim();
};

const resume = extractSection(analysisText, 1) || analysisText.substring(0, 600);
const recommandations = extractSection(analysisText, 5) || 'Voir analyse complète dans contextData.';

const insight = {
  title: isFallback
    ? `[Fallback] Analyse Externe — ${monthLabel}`
    : `Analyse Externe — ${monthLabel}`,
  description: resume.substring(0, 1000),
  suggestion: recommandations.substring(0, 1000),
  contextData: analysisText,
  confidence,
  type: 'EXTERNAL_RECOMMENDATION',
  agentType: 'EXTERNAL_ANALYSIS_AGENT',
  isFallback,
  collectedAt
};

return [{ json: insight }];
